package com.networkmonitorpro.data.entity; import androidx.room.*; @Entity public class DownloadHistory{ @PrimaryKey(autoGenerate=true) public long id; public String url,fileName,category,status,path; public int progress; public long downloaded,total,speedBps,timestamp; public boolean fiveGOnly; public DownloadHistory(String url,String fileName,String category,String status,String path,int progress,long downloaded,long total,long speedBps,long timestamp,boolean fiveGOnly){this.url=url;this.fileName=fileName;this.category=category;this.status=status;this.path=path;this.progress=progress;this.downloaded=downloaded;this.total=total;this.speedBps=speedBps;this.timestamp=timestamp;this.fiveGOnly=fiveGOnly;} }
